<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder\SmtpOutboundConfigTimeoutAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigTimeoutAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigTimeoutAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getTimeout returns null on a freshly created holder.
     */
    public function testTimeoutNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigTimeoutAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isTimeoutAssigned());
        $this->assertNull($holder->getTimeout());
    }
}
class ImplWithSmtpOutboundConfigTimeoutAttributeHolderUnitTest
{
    use SmtpOutboundConfigTimeoutAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTimeoutRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultTimeout();
    }
}
